update pages set contenu = '{"sections":[]}'::jsonb where path = '/expertises/types-de-maintenance/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Types de maintenance","mecanisme":"Six familles, un seul arbitrage. Ce qui se répare après la panne, ce qui s''entretient au calendrier, ce qui se déclenche sur un état mesuré. Cette page donne la typologie complète, puis la méthode pour la poser sur vos machines.","cta":"Lancer mon diagnostic gratuit","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, chaque technicien est évalué en entretien technique et comportemental"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, des interventions partout en France"}],"reponse":[{"texte":"Deux verbes, deux mondes. **Maintenir**, c''est agir avant la panne : la famille préventive. **Rétablir**, c''est agir une fois la défaillance survenue : la famille corrective. À côté, la maintenance améliorative modifie le bien pour le fiabiliser."}]},{"type":"probleme","punchline":"Vous connaissez la typologie. Ce n''est pas elle qui vous manque, c''est la main d''œuvre pour la tenir.","puces":[{"accroche":"Le tableau est juste, le plan ne se tient pas.","texte":"Le préventif est écrit, puis il saute dès que la production réclame la machine. Le retard s''accumule, le correctif reprend le budget."},{"accroche":"Le conditionnel demande une compétence rare.","texte":"Lire un spectre vibratoire est un métier. Peu de sites ont quelqu''un dont c''est réellement le poste."},{"accroche":"Le curatif dépend d''une ou deux personnes.","texte":"Le jour où elles sont absentes, l''usine est aveugle et l''arbitrage se fait au téléphone, dans l''urgence."},{"accroche":"Personne ne mesure.","texte":"Sans répartition chiffrée entre correctif et préventif, le dosage se décide à l''intuition, année après année."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Le diagnostic de votre parc","texte":"inventaire, criticité, reprise de votre historique de pannes, répartition réelle entre correctif et préventif."},"benefice":"Vous voyez enfin où part l''argent, machine par machine, et sur quoi agir en premier."},{"prestation":{"accroche":"La maintenance corrective et curative","texte":"diagnostic, réparation, essais, remise en service, recherche de la cause racine."},"benefice":"La ligne repart, et la même panne ne revient pas trois mois plus tard."},{"prestation":{"accroche":"Les campagnes préventives planifiées","texte":"inspections, contrôles, réglages, graissage, remplacements périodiques, vérifications réglementaires."},"benefice":"Le plan est tenu, y compris les semaines chargées où vos équipes sont prises ailleurs."},{"prestation":{"accroche":"La surveillance conditionnelle","texte":"analyse vibratoire, thermographie infrarouge, analyse d''huile, contrôle des grandeurs électriques."},"benefice":"Vous voyez la dégradation venir, et l''arrêt devient planifié au lieu d''être subi."},{"prestation":{"accroche":"Les travaux amélioratifs","texte":"fiabilisation d''un point faible, modification de conception, meilleure accessibilité d''un point de contrôle."},"benefice":"La panne sort du planning au lieu d''être entretenue."},{"prestation":{"accroche":"Un compte rendu à chaque passage","texte":"cause, travaux, pièces, relevés, recommandations, exploitables dans votre GMAO."},"benefice":"L''historique reste chez vous, même le jour où vous changez de prestataire."}],"prose":[{"texte":"Besoin d''une réparation tout de suite ? Voir le [dépannage industriel](/offres/depannage-industriel/). Besoin de tenir le préventif dans la durée ? Voir le [contrat de maintenance Zéro arrêt](/offres/zero-arret/). Migen est une [entreprise de maintenance industrielle](/offres/) présente partout en France."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation.","texte":"Quatre champs, ou un appel au 04 78 33 72 05. Vous dites ce qui casse, pas ce que vous avez déjà diagnostiqué."},{"titre":"Nous qualifions le besoin.","texte":"Parc, criticité, historique, contraintes de production, compétences déjà présentes chez vous."},{"titre":"Le diagnostic sur site.","texte":"Un référent technique passe, fait l''inventaire, classe les équipements par criticité et repère les actifs qui concentrent la charge."},{"titre":"La restitution, type par type.","texte":"Ce qui reste en correctif sans culpabilité, ce qui bascule en préventif, ce qui mérite une surveillance. Une liste priorisée, pas une étude de cinquante pages."},{"titre":"La proposition.","texte":"Périmètre, fréquences, niveaux de service, chiffrage. Intervention ponctuelle, campagnes planifiées ou abonnement, selon ce qui se justifie."},{"titre":"L''exécution et la mesure.","texte":"Nos techniciens réalisent les travaux, vous recevez un écrit à chaque passage, et le plan se révise sur les résultats mesurés."}]},{"type":"garanties","puces":[{"accroche":"La recommandation honnête.","texte":"Si un contrat complet ne se justifie pas pour votre site, nous le disons et nous proposons le niveau qui se justifie. Nous ne vendons ni logiciel ni capteur : notre conseil n''a pas d''intérêt commercial caché."},{"accroche":"Le niveau des intervenants.","texte":"Chaque technicien passe une évaluation technique et comportementale en entretien, seuls 10 % des candidats sont retenus, et les résultats de ces épreuves sont partageables."},{"accroche":"La traçabilité de bout en bout.","texte":"Un compte rendu exploitable après chaque passage, un historique par machine, des données qui restent votre propriété et qui vous sont restituées."}]},{"type":"cta","question":"Besoin de savoir quelle part de votre budget part dans l''imprévu, et quelles machines la produisent ?","bouton":"Lancer mon diagnostic gratuit","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/expertises/types-de-maintenance/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Maintenance préventive et curative d''une fonderie et d''un usinage, automobile","texte":"tenue 7 jours sur 7, depuis octobre 2023","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"},{"titre":"Reprise complète de la maintenance préventive annuelle de deux sites, e-commerce","texte":"six techniciens en permanence, prise en charge réalisée en un mois","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"Maintenance curative des convoyeurs, trieurs et packaging, logistique","texte":"deux techniciens en poste sur site","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"},{"titre":"Diagnostic sur site et réparation d''un parc machines défaillant, industrie lyonnaise","texte":"remise en état sans rachat de matériel neuf","lienLibelle":"Étude de cas JOINT LYONNAIS : défaillances machines","lienHref":"/preuves/joint-lyonnais/"},{"titre":"Préventif tenu sur un centre logistique en flux continu","texte":"10 à 20 techniciens une semaine sur deux, par créneaux de 8 heures","lienLibelle":"Étude de cas AMAZON : maintien d''un centre logistique","lienHref":"/preuves/amazon-centre-logistique/"}]},{"type":"objections","questions":[{"question":"Combien coûte tout ça ?","reponse":"Le chiffrage se fait sur devis, après le diagnostic. Il dépend du nombre d''équipements couverts, des fréquences retenues et du niveau de surveillance. Le diagnostic qui produit ce chiffrage est gratuit, et la liste priorisée vous reste même si vous ne signez pas."},{"question":"Faut-il un contrat pour faire appel à vous ?","reponse":"Non. Une panne isolée se traite en intervention ponctuelle, sans autre formalité qu''un bon de commande. Le contrat devient utile quand vous cherchez un résultat mesuré dans la durée : moins d''immobilisations, un budget lisible, un programme suivi."},{"question":"Nous avons déjà un prestataire. Comment on bascule ?","reponse":"Nous préparons la reprise pendant le préavis de votre contrat en cours : inventaire du parc, récupération des historiques et des gammes, reprise du calendrier de visites. Le premier passage Migen s''enchaîne sur le dernier passage du prestataire sortant."},{"question":"Qui répond de la sécurité pendant les interventions ?","reponse":"Plan de prévention signé et appliqué, accueil au poste suivi à la lettre, habilitations vérifiées avant le déplacement, consignation électrique, travail en hauteur, espaces confinés, zones classées. Vos procédures qualité et vos clauses de confidentialité priment sur les nôtres."},{"question":"Qui intervient sur nos machines ?","reponse":"Des techniciens salariés de Migen, évalués en entretien technique et comportemental, 10 % des candidats retenus. Huit domaines couverts : mécanique, électricité, électromécanique, automatisme, hydraulique, pneumatique, soudure et chaudronnerie, robotique."},{"question":"Couvrez-vous notre région, et les petits parcs ?","reponse":"Oui aux deux. 4 agences, Lyon (siège), Montréal, Dubaï et Madrid, et des interventions partout en France. Un atelier de cinq machines critiques mérite un plan léger mais réel, dimensionné sur votre réalité et pas sur un catalogue."}]},{"type":"ctaFinal","question":"Besoin d''un dosage décidé sur vos chiffres plutôt que sur une habitude ?","bouton":"Lancer mon diagnostic gratuit","rappel":"04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure, astreinte 24/24 et 7/7."}]'::jsonb) where path = '/expertises/types-de-maintenance/';
